'use strict';
const E=NexusEngine,KEY='as-nexus-demo-v2';
let s;try{s=JSON.parse(localStorage.getItem(KEY));E.validate(s)}catch{s=E.seed();localStorage.setItem(KEY,JSON.stringify(s))}
let lang=localStorage.getItem('nexus-lang')||'en',page='dashboard',role='admin',currency='USD',dark=localStorage.getItem('nexus-theme')==='dark',cart=[],portalClient='C01',formMode='',formExtra={},tourStep=-1;
const $=q=>document.querySelector(q),$$=q=>[...document.querySelectorAll(q)],T=(en,ar)=>lang==='ar'?ar:en,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),M=(n,c=currency,r=s.settings.rates[c])=>new Intl.NumberFormat(lang==='ar'?'ar-LB':'en-US',{style:'currency',currency:c,currencyDisplay:'narrowSymbol',maximumFractionDigits:c==='LBP'?0:2}).format(n/r),N=n=>new Intl.NumberFormat(lang==='ar'?'ar-LB':'en-US').format(n),pn=id=>{const p=s.products.find(p=>p.id===id);return p?esc(T(p.name,p.arabic)):esc(id)},cn=id=>{const c=s.clients.find(c=>c.id===id);return c?esc(T(c.name,c.arabic)):esc(id)},sn=id=>{const c=s.suppliers.find(c=>c.id===id);return c?T(c.name,c.arabic):id},wh=w=>w==='main'?T('Beirut · Main','بيروت · الرئيسي'):T('Jounieh · Branch','جونية · الفرع');
const labels={approval:['Awaiting approval','بانتظار الموافقة'],ready:['Reserved','محجوز'],backorder:['Backorder','بانتظار المخزون'],partial:['Partially fulfilled','منفّذ جزئياً'],delivered:['Delivered','تم التسليم'],cancelled:['Cancelled','ملغى'],draft:['Draft','مسوّدة'],converted:['Converted','تم التحويل'],ordered:['Ordered','تم الطلب'],received:['Received','تم الاستلام'],posted:['Posted','مرحّل'],new:['New','جديد'],qualified:['Qualified','مؤهّل'],proposal:['Proposal','عرض'],negotiation:['Negotiation','تفاوض'],won:['Won','ناجح'],lost:['Lost','خاسر'],Rent:['Rent','إيجار'],Logistics:['Logistics','شحن'],Software:['Software','برمجيات'],Marketing:['Marketing','تسويق'],Payroll:['Payroll','رواتب'],receipt:['Receipt','تحصيل'],expense:['Expense','مصروف'],supplier:['Supplier payment','دفع للمورّد'],refund:['Refund','استرداد'],create:['Order created','إنشاء طلب'],quote:['Quote created','إنشاء عرض سعر'],convert:['Quote converted','تحويل عرض السعر'],approve:['Order approved','الموافقة على الطلب'],ship:['Shipment invoiced','شحن وفوترة'],pay:['Payment received','تحصيل دفعة'],return:['Return processed','تسجيل مرتجع'],purchase:['Purchase requested','طلب شراء'],purchaseApprove:['Purchase approved','اعتماد الشراء'],receive:['Stock received','استلام مخزون'],supplierpay:['Supplier paid','دفع للمورّد'],transfer:['Stock transferred','نقل مخزون'],count:['Count submitted','إرسال الجرد'],countApprove:['Count posted','ترحيل الجرد'],expenseApprove:['Expense posted','ترحيل المصروف'],match:['Bank entry matched','مطابقة حركة البنك'],unmatch:['Match removed','إلغاء المطابقة'],settings:['Policies updated','تحديث السياسات'],cancel:['Order cancelled','إلغاء الطلب'],client:['Customer added','إضافة عميل'],lead:['Lead added','إضافة فرصة'],stage:['Stage changed','تغيير المرحلة'],bankimport:['Statement imported','استيراد كشف البنك'],reserve:['Allocation refreshed','تحديث الحجز']};
const L=x=>labels[x]?T(...labels[x]):x;
const roles={admin:['Administrator','مدير النظام'],sales:['Sales','المبيعات'],warehouse:['Warehouse','المستودع'],finance:['Finance','المالية'],procurement:['Procurement','المشتريات'],customer:['Customer portal','بوابة العميل']};
const pages={dashboard:['Overview','نظرة عامة','grid'],crm:['CRM pipeline','فرص البيع','users'],quotes:['Quotations','عروض الأسعار','file'],sales:['Sales orders','طلبات البيع','orders'],customers:['Customers','العملاء','users'],inventory:['Inventory & lots','المخزون والدفعات','box'],warehouse:['Fulfillment','تجهيز الطلبات','truck'],purchasing:['Purchasing','المشتريات','cart'],replenishment:['Replenishment','تخطيط التوريد','refresh'],finance:['Invoices & payments','الفواتير والدفعات','wallet'],expenses:['Expenses','المصاريف','wallet'],reconciliation:['Bank matching','مطابقة البنك','link'],reports:['Analytics','التحليلات','chart'],approvals:['Approvals','الموافقات','check'],intelligence:['Decision studio','استوديو القرارات','spark'],portal:['Customer portal','بوابة العميل','globe'],audit:['Audit trail','سجل العمليات','clock'],settings:['Workspace settings','إعدادات المساحة','settings']};
const title=p=>T(pages[p][0],pages[p][1]);
const btn=(text,act,args='',primary=false,ic='')=>`<button type="button" class="btn ${primary?'primary':''}" data-act="${act}" ${args}>${ic?icon(ic):''}${text}</button>`;
const badge=st=>`<span class="chip ${['ready','delivered','received','posted','won','converted'].includes(st)?'green':['approval','partial','backorder','negotiation'].includes(st)?'orange':st==='cancelled'||st==='lost'?'red':'blue'}">${L(st)}</span>`;
const panel=(name,body,sub='',extra='')=>`<section class="panel"><div class="panel-head"><div><h2>${name}</h2>${sub?`<p class="muted small">${sub}</p>`:''}</div>${extra}</div>${body}</section>`;
const empty=()=>`<div class="empty">${icon('box')}<p>${T('No records yet. Your next action will appear here.','لا توجد سجلات بعد. ستظهر عمليتك التالية هنا.')}</p></div>`;
function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty()}
const link=(text,kind,id)=>`<button class="table-link" data-act="detail" data-kind="${kind}" data-id="${id}">${esc(text)}</button>`;
const metric=(label,val,sub,ic='chart',highlight=false)=>`<div class="stat ${highlight?'highlight':''}"><div class="stat-label">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${val}</div><div class="stat-foot">${sub}</div></div>`;
function stateSave(next){const stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored&&stored.revision!==s.revision)throw Error('stale');localStorage.setItem(KEY,JSON.stringify(next));s=next}
const errors={permission:['This workspace role cannot perform this action.','هذا الدور لا يملك صلاحية تنفيذ العملية.'],stock:['Requested quantity exceeds available allocation or stock.','الكمية المطلوبة تتجاوز الحجز أو المخزون المتاح.'],credit:['Customer exposure exceeds the credit limit. Administrator must explicitly approve the override.','رصيد العميل والطلبات يتجاوز حد الائتمان. يجب أن يوافق المدير صراحةً على الاستثناء.'],commercial:['This order needs commercial approval by the administrator.','الطلب يحتاج موافقة تجارية من المدير.'],quantity:['Enter a valid whole quantity.','أدخل كمية صحيحة.'],amount:['Enter a positive valid amount.','أدخل مبلغاً صحيحاً أكبر من صفر.'],price:['Check prices and discounts (0–30%).','راجع الأسعار والخصومات (٠–٣٠٪).'],overpay:['Payment exceeds the remaining balance.','الدفعة تتجاوز الرصيد المستحق.'],status:['This action is unavailable for the current document status.','العملية غير متاحة في حالة المستند الحالية.'],complete:['This customer requires complete shipments. Reserve all remaining quantities first.','هذا العميل يتطلب تسليماً كاملاً. احجز كل الكميات المتبقية أولاً.'],returnQty:['Return exceeds the unreturned invoice quantity.','المرتجع يتجاوز الكمية المتاحة للإرجاع.'],staleCount:['Stock changed after counting. Submit a fresh count.','تغيّر المخزون بعد الجرد. سجّل جرداً جديداً.'],stale:['Another tab changed the workspace. Reload this page before continuing.','عدّلت علامة تبويب أخرى المساحة. أعد تحميل الصفحة قبل المتابعة.'],match:['Select an unmatched payment with the exact statement amount.','اختر دفعة غير مطابقة وبنفس مبلغ الحركة.'],schema:['The backup format is invalid.','صيغة النسخة الاحتياطية غير صالحة.'],lines:['Add at least one product.','أضف منتجاً واحداً على الأقل.'],client:['Check the customer and credit limit.','راجع العميل وحد الائتمان.']};
function toast(text,error=false){$('#toast').innerHTML=`<div class="toast ${error?'error':''}">${icon(error?'alert':'check')}${esc(text)}</div>`;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').innerHTML='',4500)}
function commit(type,input){try{stateSave(E.action(s,type,input,role));close();render();toast(T('Saved. Inventory and finance updated together.','تم الحفظ وتحديث المخزون والمالية معاً.'));return true}catch(e){toast(errors[e.message]?T(...errors[e.message]):T('Please check the form values.','راجع القيم المدخلة.'),true);console.error(e);return false}}
function nav(){const groups=[[T('COMMAND','القيادة'),['dashboard','intelligence','approvals']],[T('GROWTH','النمو'),['crm','quotes','sales','customers']],[T('OPERATIONS','العمليات'),['inventory','warehouse','purchasing','replenishment']],[T('FINANCE','المالية'),['finance','expenses','reconciliation','reports']],[T('WORKSPACE','المساحة'),['portal','audit','settings']]];return groups.map(([name,items])=>`<div class="nav-caption">${name}</div><nav class="nav">${items.map(p=>`<button class="nav-btn ${page===p?'active':''}" data-page="${p}" ${page===p?'aria-current="page"':''}>${icon(pages[p][2])}${title(p)}${p==='approvals'?`<span class="count">${approvalsCount()}</span>`:''}</button>`).join('')}</nav>`).join('')}
function approvalsCount(){return s.orders.filter(o=>o.status==='approval').length+s.purchases.filter(p=>p.status==='approval').length+s.counts.filter(c=>c.status==='approval').length+s.expenses.filter(e=>e.status==='approval').length}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.body.classList.toggle('dark-mode',dark);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">N</div><div><div class="brand-name">AS NEXUS</div><div class="brand-sub">COMMERCE INTELLIGENCE</div></div></div><div class="workspace"><div class="avatar">ND</div><div><strong>${T('Nexa Distribution','نكسا للتوزيع')}</strong><div class="tiny muted">${T('2 locations · USD base','موقعان · الدولار عملة الأساس')}</div></div></div>${nav()}<div class="studio">${T('A product concept by','منتج تجريبي من')}<br><a href="https://asdesignlb.com" target="_blank" rel="noreferrer">AS DESIGN LB ${icon('link')}</a></div></aside><main class="main"><header class="topbar"><div class="crumb"><button class="icon-btn mobile-toggle" data-act="menu" aria-label="Menu">${icon('menu')}</button><span class="muted">${T('Workspace','مساحة العمل')}</span>${icon('chev')}<strong>${title(page)}</strong></div><div class="top-actions"><button class="search-button" data-act="search" aria-label="${lang==='ar'?'بحث':'Search'}">${icon('search')}<span>${T('Find anything','ابحث عن أي شيء')}</span><span class="key">⌘ / Ctrl K</span></button><select id="currency" aria-label="${T('Display currency','عملة العرض')}">${['USD','EUR','LBP'].map(c=>`<option ${c===currency?'selected':''}>${c}</option>`).join('')}</select><button class="icon-btn" data-act="language" aria-label="${T('Switch to Arabic','التبديل للإنجليزية')}">${lang==='en'?'ع':'EN'}</button><button class="icon-btn" data-act="theme" aria-label="${T('Switch theme','تغيير المظهر')}">${dark?'☀':'◐'}</button><div class="profile"><div class="avatar">AM</div><select id="role" aria-label="${T('Demo role','الدور التجريبي')}">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${role===k?'selected':''}>${T(...v)}</option>`).join('')}</select></div></div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">AS NEXUS / 02</div><h1>${title(page)}</h1><p class="subtitle">${subtitles[page]?T(...subtitles[page]):T('Connected operations. Clear decisions.','عمليات مترابطة وقرارات واضحة.')}</p></div><div class="heading-actions">${btn(T('Guided tour','جولة تعريفية'),'tour','',false,'play')}${btn(T('Export CSV','تصدير CSV'),'export','',false,'download')}${primaryAction()}</div></div>${views[page]()}<div class="footer-note"><span>AS NEXUS 2 · AS DESIGN LB</span><span>${T('Interactive concept · Saved on this browser · Scenario date: 08 Oct 2026','نموذج تفاعلي · محفوظ في هذا المتصفح · تاريخ السيناريو: ٨ تشرين الأول ٢٠٢٦')}</span></div></div></main></div>`;}
const subtitles={dashboard:['Your business, in one connected view.','رؤية مترابطة لكل أعمالك.'],crm:['Turn opportunities into revenue.','حوّل الفرص إلى إيرادات.'],quotes:['Build proposals that flow into fulfillment.','عروض أسعار تتصل بالتنفيذ مباشرةً.'],sales:['Multi-item orders. Credit checks. Partial fulfillment.','طلبات متعددة المنتجات، ائتمان، وتسليم على مراحل.'],inventory:['Every unit, lot, expiry and location accounted for.','كل قطعة ودفعة وصلاحية وموقع محسوب.'],warehouse:['Allocate by earliest expiry. Ship what is ready.','احجز الأقرب انتهاءً واشحن الجاهز.'],purchasing:['Request, approve, receive and pay with one trail.','طلب واعتماد واستلام ودفع بسجل واحد.'],replenishment:['Balance live demand against stock and incoming supply.','وازن الطلب مع المخزون والتوريد القادم.'],finance:['Invoice only shipped items. Track each payment.','فوترة الكميات المشحونة وتتبع كل دفعة.'],reconciliation:['Match bank entries to recorded payments without posting twice.','طابق حركة البنك مع الدفعات المسجلة دون تكرار الترحيل.'],reports:['Profitability, aging, inventory and financial evidence.','ربحية وأعمار ديون ومخزون وأدلة مالية.'],intelligence:['Explain exceptions. Model your next move.','فسّر الاستثناءات واختبر خطوتك القادمة.'],portal:['A wholesale shopping experience connected to the ERP.','تجربة شراء بالجملة متصلة بالنظام.'],settings:['Control policies, currencies and your local workspace.','تحكم بالسياسات والعملات ومساحتك المحلية.']};
function primaryAction(){const actions={crm:['New opportunity','فرصة جديدة','lead'],quotes:['New quotation','عرض سعر جديد','quote'],sales:['New order','طلب جديد','create'],customers:['Add customer','إضافة عميل','client'],inventory:['Stock count','جرد مخزون','count'],purchasing:['Purchase request','طلب شراء','purchase'],expenses:['Submit expense','تسجيل مصروف','expense'],reconciliation:['Import CSV','استيراد CSV','bankimport']};const a=actions[page];return a?btn(T(a[0],a[1]),'form',`data-mode="${a[2]}"`,true,'plus'):''}
function orderTable(orders){return table([T('Order / customer','الطلب / العميل'),T('Items','المنتجات'),T('Value','القيمة'),T('Fulfillment','التنفيذ'),T('Status','الحالة')],orders.map(o=>[`${link(o.id,'order',o.id)}<div class="cell-sub">${cn(o.client)}</div>`,o.lines.map(l=>`${pn(l.product)} × ${N(l.qty)}`).join('<br>'),M(E.totals(o).gross),`<div class="progressbar"><i style="width:${o.lines.reduce((a,l)=>a+l.shipped,0)/o.lines.reduce((a,l)=>a+l.qty,0)*100}%"></i></div>${N(o.lines.reduce((a,l)=>a+l.shipped,0))} / ${N(o.lines.reduce((a,l)=>a+l.qty,0))}`,badge(o.status)]))}
function trend(){const vals=[1,2,3,4,5,6,7,8].map(d=>({date:'2026-10-0'+d,revenue:0,profit:0}));s.journal.forEach(j=>{const v=vals.find(x=>x.date===j.date);if(v)j.lines.forEach(l=>{if(l.account==='Revenue'){v.revenue+=l.credit-l.debit;v.profit+=l.credit-l.debit}if(l.account==='Cost of sales')v.profit-=l.debit-l.credit})});const max=Math.max(...vals.map(v=>Math.abs(v.revenue)),...vals.map(v=>Math.abs(v.profit)),1);return `<div class="chart-bars">${vals.map((v,i)=>`<div class="bar-day"><div class="bar-values"><div class="bar revenue" style="height:${Math.max(1,Math.abs(v.revenue)/max*145)}px" title="${esc(M(v.revenue))}"></div><div class="bar profit ${v.profit<0?'negative':''}" style="height:${Math.max(1,Math.abs(v.profit)/max*145)}px" title="${esc(M(v.profit))}"></div></div><span>0${i+1} Oct</span></div>`).join('')}</div><div class="legend"><i></i>${T('Net sales','صافي المبيعات')}<i class="profit"></i>${T('Gross profit · daily postings','الربح الإجمالي · حسب يوم الترحيل')}</div>`}
function dashboard(){const m=E.metrics(s),expire=s.lots.filter(l=>l.qty&&l.status==='saleable'&&l.expiry<='2026-11-07'),rp=s.products.filter(p=>E.replenishment(s,p).suggested),flow=[['quotes',s.quotes.filter(q=>q.status==='draft').length],['sales',m.open],['warehouse',s.orders.filter(o=>['ready','partial'].includes(o.status)).length],['finance',s.invoices.filter(i=>E.due(i)>0).length]];return `<div class="overview-hero"><div><span class="hero-pill">${T('CONNECTED COMMERCE','تجارة مترابطة')}</span><h2>${T('A sharper view. A stronger business.','رؤية أوضح. أعمال أقوى.')}</h2><p>${T('Act on the exceptions. Keep your whole operation in sync.','عالج الاستثناءات وخلّي كل عملياتك متزامنة.')}</p></div>${btn(T('Review priorities','راجع الأولويات'),'goto','data-page="intelligence"',true,'spark')}</div><div class="stats">${metric(T('Net sales','صافي المبيعات'),M(m.revenue),T('Shipped & invoiced','مشحون ومفوتر'),'orders')}${metric(T('Gross margin','هامش الربح'),N(m.margin)+'%',M(m.profit), 'chart')}${metric(T('Cash balance','رصيد النقد'),M(m.cash),T('Ledger balance','الرصيد في الدفتر'),'wallet',true)}${metric(T('Net operating profit','صافي الربح التشغيلي'),M(m.netProfit),T('After operating expenses','بعد المصاريف التشغيلية'),'target')}</div><div class="flow-strip">${flow.map(([p,n],i)=>`<button data-page="${p}"><span class="flow-num">0${i+1}</span><div><strong>${title(p)}</strong><span>${N(n)} ${T('active documents','مستندات نشطة')}</span></div>${icon(pages[p][2])}</button>`).join('')}</div><div class="grid-main">${panel(T('Performance pulse','نبض الأداء'),`<div class="panel-body">${trend()}</div>`,T('October 2026 · Actual journal entries','تشرين الأول ٢٠٢٦ · حركات فعلية'))}${panel(T('Needs your attention','بحاجة لقرارك'),`<div class="panel-body"><div class="decision">${icon('lock')}<div><strong>${N(approvalsCount())} ${T('documents awaiting approval','مستندات بانتظار الموافقة')}</strong><p>${T('Commercial, credit, purchasing and expense controls.','رقابة تجارية وائتمانية ومشتريات ومصاريف.')}</p>${btn(T('Open approvals','افتح الموافقات'),'goto','data-page="approvals"')}</div></div><div class="decision">${icon('clock')}<div><strong>${N(expire.reduce((a,l)=>a+l.qty,0))} ${T('units approaching expiry','قطعة تقترب من انتهاء الصلاحية')}</strong><p>${T('30-day expiry window. FEFO protects allocation.','نافذة ٣٠ يوماً. الحجز يبدأ بالأقرب انتهاءً.')}</p>${btn(T('Review lots','راجع الدفعات'),'goto','data-page="inventory"')}</div></div><div class="decision">${icon('refresh')}<div><strong>${N(rp.length)} ${T('products below forecast minimum','منتجات دون الحد الأدنى المتوقع')}</strong>${btn(T('Plan replenishment','خطط التوريد'),'goto','data-page="replenishment"')}</div></div></div>`)}</div>${panel(T('Order command center','مركز قيادة الطلبات'),orderTable(s.orders.filter(o=>!['delivered','cancelled'].includes(o.status))),T('Click an order to approve, allocate or ship.','اضغط على طلب للموافقة أو الحجز أو الشحن.'))}`}
function crm(){const stages=['new','qualified','proposal','negotiation','won','lost'],prob={new:.1,qualified:.25,proposal:.5,negotiation:.75,won:1,lost:0};return `<div class="stats">${metric(T('Open pipeline','الفرص المفتوحة'),M(s.leads.filter(l=>!['won','lost'].includes(l.stage)).reduce((a,l)=>a+l.value,0)),T('Potential deal value','قيمة الصفقات المحتملة'))}${metric(T('Weighted forecast','التوقع المرجّح'),M(s.leads.filter(l=>!['won','lost'].includes(l.stage)).reduce((a,l)=>a+l.value*prob[l.stage],0)),T('Stage probability model','نموذج احتمالية المرحلة'))}${metric(T('Won opportunities','الفرص الناجحة'),N(s.leads.filter(l=>l.stage==='won').length),T('Quote conversion closes the loop','تحويل العرض يغلق الدورة'))}${metric(T('Active quotations','العروض النشطة'),N(s.quotes.filter(q=>q.status==='draft').length),T('Ready to convert','جاهزة للتحويل'))}</div><div class="kanban">${stages.map(st=>`<section class="kanban-col"><header>${L(st)} <span>${s.leads.filter(l=>l.stage===st).length}</span></header>${s.leads.filter(l=>l.stage===st).map(l=>`<article class="deal"><div class="tiny muted">${l.id}</div><h3>${esc(T(l.name,l.arabic))}</h3><p>${cn(l.client)}</p><strong>${M(l.value)}</strong><select aria-label="${T('Deal stage','مرحلة الفرصة')}" data-lead="${l.id}">${stages.map(z=>`<option value="${z}" ${z===st?'selected':''}>${L(z)}</option>`).join('')}</select>${btn(T('Create quotation','إنشاء عرض'),'form',`data-mode="quote" data-lead="${l.id}"`)}</article>`).join('')}</section>`).join('')}</div>`}
function quotations(){return panel(title('quotes'),table([T('Quote','العرض'),T('Customer','العميل'),T('Lines','البنود'),T('Value','القيمة'),T('Status','الحالة'),T('Action','العملية')],s.quotes.map(q=>[link(q.id,'quote',q.id),cn(q.client),N(q.lines.length),M(E.totals(q).gross,q.currency,q.rate),badge(q.status),q.status==='draft'?btn(T('Convert to order','تحويل لطلب'),'direct',`data-type="convert" data-id="${q.id}"`,true):link(q.order,'order',q.order)])),T('Exchange rates are captured when the document is created.','سعر الصرف يُثبّت عند إنشاء المستند.'))}
function sales(){return `${filters()}${panel(title('sales'),orderTable(s.orders))}`}
function filters(){return `<div class="list-tools"><label>${icon('search')}<input id="table-search" placeholder="${T('Filter visible records…','تصفية السجلات الظاهرة…')}" aria-label="${T('Filter records','تصفية السجلات')}"></label><span class="muted small">${T('Live operational data','بيانات العمليات الحالية')}</span></div>`}
function inventory(){return `<div class="stats">${metric(T('Inventory value','قيمة المخزون'),M(E.metrics(s).inventory),T('Actual lot cost','كلفة الدفعة الفعلية'),'box')}${metric(T('On hand units','الكمية الموجودة'),N(E.metrics(s).units),T('Across both locations','في الموقعين'),'building')}${metric(T('Reserved units','الكمية المحجوزة'),N(s.lots.reduce((a,l)=>a+l.reserved,0)),T('Linked to approved orders','متصلة بالطلبات المعتمدة'),'lock')}${metric(T('Quarantine units','كمية الحجر'),N(s.lots.filter(l=>l.status==='quarantine').reduce((a,l)=>a+l.qty,0)),T('Excluded from saleable stock','مستبعدة من البيع'),'alert')}</div>${filters()}${panel(T('Stock by product','المخزون حسب المنتج'),table([T('Product','المنتج'),T('Beirut','بيروت'),T('Jounieh','جونية'),T('Saleable available','متاح للبيع'),T('Min / target','الأدنى / المستهدف'),T('Actions','العمليات')],s.products.map(p=>[`${link(pn(p.id),'product',p.id)}<div class="cell-sub">${p.sku}</div>`,`${N(p.stock.main)} <small class="muted">(${N(p.reserved.main)} ${T('held','حجز')})</small>`,`${N(p.stock.branch)} <small class="muted">(${N(p.reserved.branch)} ${T('held','حجز')})</small>`,N(E.available(s,p.id)),`${N(p.reorder)} / ${N(p.target)}`,btn(T('Transfer','نقل'),'form',`data-mode="transfer" data-product="${p.id}"`)])))}<div class="section-space">${panel(T('Virtual kits','مجموعات افتراضية'),`<div class="kit-grid">${s.kits.map(k=>`<article class="kit-card"><div class="kit-visual">${icon('box')}${icon('plus')}${icon('box')}</div><h3>${T(k.name,k.arabic)}</h3><p>${k.items.map(i=>`${N(i.qty)} × ${pn(i.product)}`).join(' + ')}</p><div class="kit-bottom"><strong>${M(k.items.reduce((a,i)=>a+i.qty*i.unit,0))}</strong><span class="chip green">${N(Math.min(...k.items.map(i=>Math.floor(E.available(s,i.product)/i.qty))))} ${T('available','متاح')}</span></div></article>`).join('')}</div>`,T('Kits reserve real components; stock is never duplicated.','المجموعات تحجز مكوّناتها الفعلية دون تكرار المخزون.'))}</div>`}
function warehouse(){const open=s.orders.filter(o=>['ready','partial','backorder'].includes(o.status));return `<div class="guide"><div><h3>${T('FEFO allocation across locations','حجز الأقرب انتهاءً في كل المواقع')}</h3><p>${T('Expired and quarantined lots are excluded. Ship partially or enforce complete delivery per customer.','الدفعات المنتهية والمحجورة مستبعدة. تسليم جزئي أو كامل حسب سياسة العميل.')}</p></div>${btn(T('Submit count','سجّل جرد'),'form','data-mode="count"')}</div>${panel(T('Fulfillment queue','قائمة التجهيز'),orderTable(open))}<div class="section-space">${panel(T('Shipment history','سجل الشحن'),table([T('Shipment','الشحنة'),T('Order','الطلب'),T('Invoice','الفاتورة'),T('Units','الكمية'),T('Date','التاريخ')],s.shipments.map(h=>[h.id,link(h.order,'order',h.order),link(h.invoice,'invoice',h.invoice),N(h.lines.reduce((a,l)=>a+l.qty,0)),h.date])))}${panel(T('Cycle counts','الجرد الدوري'),table([T('Count','الجرد'),T('Product / location','المنتج / الموقع'),T('Book','بالدفتر'),T('Counted','الفعلي'),T('Variance','الفرق'),T('Status','الحالة')],s.counts.map(c=>[c.id,`${pn(c.product)}<div class="cell-sub">${wh(c.warehouse)}</div>`,N(c.book),N(c.counted),N(c.variance),c.status==='approval'?btn(T('Approve','اعتماد'),'direct',`data-type="countApprove" data-id="${c.id}"`):badge(c.status)])))}</div>`}
function purchasing(){return `${filters()}${panel(T('Purchase orders','طلبات الشراء'),table([T('Purchase','الشراء'),T('Supplier','المورّد'),T('Items','البنود'),T('Received','المستلم'),T('Committed value','قيمة الالتزام'),T('Status','الحالة')],s.purchases.map(p=>[link(p.id,'purchase',p.id),sn(p.supplier),p.lines.map(l=>`${pn(l.product)} × ${N(l.qty)}`).join('<br>'),`${N(p.lines.reduce((a,l)=>a+l.received,0))} / ${N(p.lines.reduce((a,l)=>a+l.qty,0))}`,M(p.lines.reduce((a,l)=>a+l.qty*l.unit,0)),badge(p.status)])))}<div class="section-space">${panel(T('Supplier comparison','مقارنة المورّدين'),table([T('Supplier','المورّد'),T('Illustrative lead time','مهلة نموذجية'),T('Price index','مؤشر السعر'),T('Open payable','الرصيد المستحق')],s.suppliers.map(p=>[sn(p.id),`${N(p.lead)} ${T('days','أيام')}`,N(p.factor*100)+'%',M(p.opening+s.purchases.filter(z=>z.supplier===p.id).reduce((a,z)=>a+z.lines.reduce((n,l)=>n+l.received*l.unit,0)-z.paid,0))])),T('Demo supplier prices and lead times, editable in source.','أسعار ومهل مورّدين نموذجية قابلة للتعديل في المصدر.'))}</div>`}
function replenish(){return `<div class="guide"><div><h3>${T('Forecast = saleable stock − open demand + incoming supply','المتوقع = مخزون صالح − طلب مفتوح + توريد قادم')}</h3><p>${T('Draft requests also count as planned supply to avoid duplicate proposals. Reserved stock is counted once.','طلبات الشراء المعلقة تُحتسب كتوريد مخطط لتجنّب التكرار. المخزون المحجوز يُحتسب مرة واحدة.')}</p></div></div>${panel(T('Min / max planner','مخطط الحد الأدنى والأقصى'),table([T('Product','المنتج'),T('Saleable','صالح للبيع'),T('Demand','الطلب'),T('Incoming','القادم'),T('Forecast','المتوقع'),T('Suggested','المقترح'),T('Action','العملية')],s.products.map(p=>{const r=E.replenishment(s,p);return [pn(p.id),N(r.stock),N(r.demand),N(r.incoming),`<span class="chip ${r.forecast<p.reorder?'orange':'green'}">${N(r.forecast)}</span>`,N(r.suggested),r.suggested?btn(T('Create request','طلب شراء'),'form',`data-mode="purchase" data-product="${p.id}" data-qty="${r.suggested}"`):'—']})))}`}
function invoiceTable(invoices){return table([T('Invoice','الفاتورة'),T('Customer','العميل'),T('Total','الإجمالي'),T('Credit notes','الإشعارات الدائنة'),T('Paid','المدفوع'),T('Due','المستحق')],invoices.map(i=>[`${link(i.id,'invoice',i.id)}<div class="cell-sub">${i.order} · ${i.currency}</div>`,cn(i.client),M(i.amount),M(i.credit),M(i.paid),`<span class="chip ${E.due(i)>0?'orange':'green'}">${M(E.due(i))}</span>`]))}
function finance(){const m=E.metrics(s);return `<div class="stats">${metric(T('Accounts receivable','الذمم المدينة'),M(m.receivables),T('Invoices + opening balances','الفواتير والأرصدة الافتتاحية'))}${metric(T('Accounts payable','الذمم الدائنة'),M(m.payables),T('Received purchases + opening','المشتريات المستلمة والافتتاحي'))}${metric(T('Tax payable','ضريبة مستحقة'),M(-E.balance(s,'Tax payable')),T('Illustrative document taxes','ضرائب نموذجية للمستندات'))}${metric(T('Bank balance','رصيد البنك'),M(m.cash),T('Cash ledger','دفتر النقد'),'wallet',true)}</div>${filters()}${panel(T('Sales invoices','فواتير المبيعات'),invoiceTable(s.invoices))}<div class="section-space">${panel(T('Payment register','سجل الدفعات'),table([T('Payment','الدفعة'),T('Reference','المرجع'),T('Type','النوع'),T('Amount','المبلغ'),T('Bank matched','مطابق للبنك')],s.payments.map(p=>[p.id,p.ref,L(p.kind),M(p.amount),p.matched?badge('posted'):'—'])))}</div>`}
function customers(){return `${filters()}${panel(title('customers'),table([T('Customer','العميل'),T('City','المدينة'),T('Tier','الفئة'),T('Credit limit','حد الائتمان'),T('Outstanding','الرصيد'),T('Shipping advice','سياسة التسليم')],s.clients.map(c=>[`${link(cn(c.id),'client',c.id)}<div class="cell-sub">${c.id}</div>`,city(c.city),tier(c.tier),M(c.limit),M(E.outstanding(s,c.id)),c.partial?T('Partial allowed','الجزئي مسموح'):T('Complete only','كامل فقط')])))}`}
const city=x=>esc(T(x,({Beirut:'بيروت',Zahle:'زحلة',Jounieh:'جونية',Tripoli:'طرابلس',Baalbek:'بعلبك'})[x]||x)),tier=x=>T(x,({Platinum:'بلاتيني',Gold:'ذهبي',Silver:'فضي'})[x]||x);
function expenses(){return panel(title('expenses'),table([T('Expense','المصروف'),T('Category','الفئة'),T('Amount','المبلغ'),T('Date','التاريخ'),T('Status','الحالة'),T('Action','العملية')],s.expenses.map(e=>[e.id,L(e.category),M(e.amount),e.date,badge(e.status),e.status==='approval'?btn(T('Approve & post','اعتماد وترحيل'),'direct',`data-type="expenseApprove" data-id="${e.id}"`):'—'])),T('Submitted expenses affect cash and profit only after approval.','المصاريف تؤثر على النقد والربح بعد الموافقة فقط.'))}
function reconciliation(){return `${panel(T('Bank statement','كشف البنك'),table([T('Date','التاريخ'),T('Reference','المرجع'),T('Amount','المبلغ'),T('Match','المطابقة')],s.statements.map(b=>[b.date,esc(b.reference==='Unidentified deposit'?T('Unidentified deposit','إيداع غير محدد'):b.reference),M(b.amount),b.match?`${b.match} ${btn(T('Undo','تراجع'),'direct',`data-type="unmatch" data-id="${b.id}"`)}`:btn(T('Match payment','طابق دفعة'),'form',`data-mode="match" data-id="${b.id}"`)])),T('Exact amount match. An unmatched deposit stays unresolved.','مطابقة بنفس المبلغ. الإيداع غير المحدد يبقى معلّقاً.'))}<div class="guide section-space"><div><h3>${T('No duplicate cash entries','دون تكرار الحركات النقدية')}</h3><p>${T('Matching links the statement to an existing payment. It never creates a second journal entry.','المطابقة تربط كشف البنك بدفعة موجودة ولا تنشئ قيداً ثانياً.')}</p></div>${icon('check')}</div>`}
function reports(){const m=E.metrics(s),profitCustomers=s.clients.map(c=>({c,revenue:s.invoices.filter(i=>i.client===c.id).reduce((a,i)=>a+i.net-i.lines.reduce((n,l)=>n+E.round(l.net*l.returned/l.qty),0),0),cogs:s.invoices.filter(i=>i.client===c.id).flatMap(i=>i.lines).reduce((a,l)=>a+(l.allocations.length?l.allocations.reduce((n,a)=>n+(a.qty-a.returned)*a.unitCost,0):(l.qty-l.returned)*l.unitCost),0)})),abc=s.products.map(p=>({p,value:s.lots.filter(l=>l.product===p.id&&l.status!=='quarantine').reduce((a,l)=>a+l.qty*l.unitCost,0)})).sort((a,b)=>b.value-a.value);let cumulative=0;return `<div class="report-grid">${panel(T('Profit & loss','الأرباح والخسائر'),`<div class="panel-body financial-lines">${[[T('Net revenue','صافي الإيرادات'),m.revenue],[T('Cost of sales','كلفة المبيعات'),-m.cogs],[T('Gross profit','الربح الإجمالي'),m.profit],[T('Operating expenses & variance','المصاريف التشغيلية وفرق الجرد'),-m.expenses],[T('Net operating profit','صافي الربح التشغيلي'),m.netProfit]].map(([l,v],i)=>`<div class="${i===4?'total':''}"><span>${l}</span><strong>${M(v)}</strong></div>`).join('')}</div>`)}${panel(T('Receivable aging','أعمار الديون'),`<div class="panel-body financial-lines"><div><span>${T('Opening balances · age unavailable','أرصدة افتتاحية · العمر غير متاح')}</span><strong>${M(s.clients.reduce((a,c)=>a+c.opening,0))}</strong></div>${[[T('Not yet due','غير مستحق بعد'),-Infinity,0],[T('1–30 days overdue','متأخر ١–٣٠ يوم'),1,30],[T('31–60 days overdue','متأخر ٣١–٦٠ يوم'),31,60],[T('61+ days overdue','متأخر أكثر من ٦٠ يوماً'),61,Infinity]].map(([l,min,max])=>{const val=s.invoices.filter(i=>{const d=Math.floor((new Date(E.today)-new Date(i.dueDate))/864e5);return d>=min&&d<=max}).reduce((a,i)=>a+E.due(i),0);return `<div><span>${l}</span><strong>${M(val)}</strong></div>`}).join('')}</div>`,T('Aging is based on the scenario date and invoice due date.','العمر محسوب بتاريخ السيناريو وتاريخ استحقاق الفاتورة.'))}</div><div class="section-space">${panel(T('Customer profitability','ربحية العملاء'),table([T('Customer','العميل'),T('Net sales','صافي البيع'),T('Cost','الكلفة'),T('Gross profit','الربح الإجمالي'),T('Margin','الهامش')],profitCustomers.map(({c,revenue,cogs})=>[cn(c.id),M(revenue),M(cogs),M(revenue-cogs),revenue?N(E.round((revenue-cogs)/revenue*100))+'%':'—'])),T('Gross profit before shared operating expenses.','ربح إجمالي قبل المصاريف التشغيلية المشتركة.'))}${panel(T('ABC inventory value','تصنيف قيمة المخزون ABC'),table([T('Product','المنتج'),T('Value','القيمة'),T('Cumulative share','النسبة التراكمية'),T('Class','التصنيف')],abc.map(({p,value})=>{let before=cumulative;cumulative+=value;return [pn(p.id),M(value),N(E.round(cumulative/m.inventory*100))+'%',`<span class="chip blue">${before/m.inventory<.8?'A':before/m.inventory<.95?'B':'C'}</span>`]})),T('Ranks physical inventory by actual carrying value.','ترتيب المخزون الفعلي حسب قيمته الدفترية.'))}</div>`}
function approvals(){const orders=s.orders.filter(o=>o.status==='approval');return `<div class="guide"><div><h3>${N(approvalsCount())} ${T('decisions in your queue','قرارات بانتظارك')}</h3><p>${T('Order approvals evaluate commercial policy and total customer credit exposure. Overrides are explicit and audited.','تقيّم الموافقات السياسة التجارية والتعرّض الائتماني الكامل للعميل. الاستثناءات صريحة ومسجّلة.')}</p></div>${icon('lock')}</div>${panel(T('Sales approvals','موافقات البيع'),orderTable(orders))}<div class="section-space">${panel(T('Other approvals','موافقات أخرى'),table([T('Reference','المرجع'),T('Type','النوع'),T('Value / variance','القيمة / الفرق'),T('Action','العملية')],[...s.purchases.filter(p=>p.status==='approval').map(p=>[link(p.id,'purchase',p.id),T('Purchase request','طلب شراء'),M(p.lines.reduce((a,l)=>a+l.qty*l.unit,0)),btn(T('Approve','اعتماد'),'direct',`data-type="purchaseApprove" data-id="${p.id}"`)]),...s.expenses.filter(e=>e.status==='approval').map(e=>[e.id,L(e.category),M(e.amount),btn(T('Approve','اعتماد'),'direct',`data-type="expenseApprove" data-id="${e.id}"`)]),...s.counts.filter(c=>c.status==='approval').map(c=>[c.id,T('Stock count','جرد مخزون'),N(c.variance),btn(T('Approve','اعتماد'),'direct',`data-type="countApprove" data-id="${c.id}"`)])]))}</div>`}
function intelligence(){const m=E.metrics(s),risk=s.clients.filter(c=>E.outstanding(s,c.id)>c.limit),rp=s.products.map(p=>({p,r:E.replenishment(s,p)})).filter(x=>x.r.suggested);return `<div class="decision-hero"><div class="hero-orbit">${icon('spark')}</div><div><div class="eyebrow">NEXUS DECISION STUDIO</div><h2>${T('Know what matters next.','اعرف وين قرارك القادم.')}</h2><p>${T('Transparent rules, live workspace evidence and an interactive margin model.','قواعد واضحة وأدلة من المساحة ونموذج تفاعلي للهامش.')}</p></div></div><div class="grid-main">${panel(T('Ask your workspace','اسأل مساحة عملك'),`<div class="panel-body"><div class="ask-row"><input id="ask-input" placeholder="${T('Try: stock, credit, profit, cash…','جرّب: مخزون، ائتمان، ربح، نقد…')}">${btn(T('Explain','فسّر'),'ask','',true)}</div><div class="suggestions">${[[T('Credit exposure','التعرّض الائتماني'),'credit'],[T('Reorder priorities','أولوية التوريد'),'stock'],[T('Profit drivers','عوامل الربح'),'profit']].map(([l,q])=>btn(l,'ask',`data-query="${q}"`)).join('')}</div><div id="answer" class="answer"><strong>${T('Evidence, with every answer.','دليل مع كل جواب.')}</strong><p>${T('This concept uses deterministic analysis of your demo data. A live AI service is a future integration.','هذا النموذج يحلّل بيانات العرض بقواعد محددة. خدمة الذكاء الاصطناعي الحية تكامل مستقبلي.')}</p></div></div>`)}${panel(T('Priority signals','إشارات الأولوية'),`<div class="panel-body"><div class="decision"><div><strong>${N(risk.length)} ${T('customers over credit limit','عملاء تجاوزوا حد الائتمان')}</strong><p>${risk.map(c=>cn(c.id)).join(' · ')||T('All within limits','كلهم ضمن الحدود')}</p>${btn(T('Review customers','راجع العملاء'),'goto','data-page="customers"')}</div></div><div class="decision"><div><strong>${N(rp.length)} ${T('replenishment exceptions','استثناءات توريد')}</strong><p>${rp.map(x=>pn(x.p.id)).join(' · ')||T('Forecast above minimum','المتوقع فوق الحد الأدنى')}</p>${btn(T('Open planner','افتح المخطط'),'goto','data-page="replenishment"')}</div></div><div class="decision"><div><strong>${M(m.receivables)} ${T('to collect','للتحصيل')}</strong><p>${T('Includes opening receivables and outstanding invoices.','يشمل الأرصدة الافتتاحية والفواتير المستحقة.')}</p></div></div></div>`)}</div>${panel(T('Margin scenario','سيناريو الهامش'),`<div class="panel-body simulator"><div><label>${T('Sales volume change','تغيّر حجم البيع')} <strong id="sim-volume-value">+10%</strong><input type="range" id="sim-volume" min="-30" max="80" value="10"></label><label>${T('Price discount','خصم السعر')} <strong id="sim-discount-value">5%</strong><input type="range" id="sim-discount" min="0" max="30" value="5"></label><label>${T('Unit cost increase','زيادة كلفة الوحدة')} <strong id="sim-cost-value">0%</strong><input type="range" id="sim-cost" min="0" max="30" value="0"></label></div><div id="sim-result"></div></div>`,T('Illustrative linear model. Fixed expenses remain constant; taxes and capacity constraints are excluded.','نموذج خطي توضيحي. المصاريف ثابتة؛ الضرائب وقيود الطاقة مستبعدة.'))}`}
function portal(){const c=s.clients.find(c=>c.id===portalClient),cartTotal=cart.reduce((a,l)=>a+l.qty*l.unit*(1-(l.discount||0)/100),0);return `<div class="portal-hero"><div><div class="eyebrow">NEXA PARTNER EXPERIENCE</div><h2>${T('Your next collection starts here.','مجموعتك القادمة تبدأ هون.')}</h2><p>${T('Wholesale ordering, real availability and account visibility.','شراء بالجملة، توافر فعلي ورؤية لحسابك.')}</p><select id="portal-client">${s.clients.map(z=>`<option value="${z.id}" ${z.id===c.id?'selected':''}>${cn(z.id)}</option>`).join('')}</select></div><div class="portal-total"><span>${T('Account outstanding','الرصيد المستحق')}</span><strong>${M(E.outstanding(s,c.id))}</strong><span>${T('Credit limit','حد الائتمان')}: ${M(c.limit)}</span></div></div><div class="portal-layout"><div><div class="catalog">${s.products.map((p,i)=>`<article class="product-card"><div class="product-art color-${i%4}"><div class="bottle"><div class="bottle-cap"></div><span>NEXA<br><small>${p.sku}</small></span></div><span class="product-category">${T(p.category,({'Skin care':'العناية بالبشرة','Sun protection':'الحماية من الشمس','Body care':'العناية بالجسم','Hair care':'العناية بالشعر'})[p.category])}</span></div><div class="tiny muted">${p.sku}</div><h3>${pn(p.id)}</h3><div class="cell-sub">${N(E.available(s,p.id))} ${T('available','متاح')}</div><div class="product-bottom"><strong>${M(p.price)}</strong>${btn(T('Add','أضف'),'cartadd',`data-product="${p.id}"`,false,'plus')}</div></article>`).join('')}</div><div class="section-space">${panel(T('Curated kits','مجموعات مختارة'),`<div class="kit-grid">${s.kits.map(k=>`<article class="kit-card"><h3>${T(k.name,k.arabic)}</h3><p>${k.items.map(i=>`${N(i.qty)} × ${pn(i.product)}`).join(' + ')}</p><strong>${M(k.items.reduce((a,i)=>a+i.qty*i.unit,0))}</strong>${btn(T('Add kit','أضف المجموعة'),'kitadd',`data-id="${k.id}"`,true)}</article>`).join('')}</div>`)}</div></div><aside class="cart-panel"><div class="panel-head"><h2>${T('Your order','طلبك')}</h2><span class="chip blue">${N(cart.length)}</span></div><div class="panel-body">${cart.map((l,i)=>`<div class="cart-line"><div><strong>${pn(l.product)}</strong><small>${M(l.unit)} ${l.kit?'· '+l.kit:''}</small></div><input type="number" min="1" max="9999" value="${l.qty}" data-cart="${i}" aria-label="${esc(pn(l.product))}"><button class="icon-btn" data-act="cartremove" data-index="${i}" aria-label="${T('Remove','حذف')}">${icon('close')}</button></div>`).join('')||empty()}<div class="cart-total"><span>${T('Order total','إجمالي الطلب')}</span><strong>${M(cartTotal)}</strong></div>${btn(T('Submit for approval','إرسال للموافقة'),'cartsubmit','',true)}<p class="tiny muted cart-note">${T('Submitting creates a sales order. Stock is reserved after approval. No online payment is processed.','الإرسال ينشئ طلب بيع. المخزون يحجز بعد الموافقة. لا يتم دفع إلكتروني.')}</p></div></aside></div><div class="section-space">${panel(T('Your orders','طلباتك'),orderTable(s.orders.filter(o=>o.client===c.id)))}${panel(T('Your invoices','فواتيرك'),invoiceTable(s.invoices.filter(i=>i.client===c.id)))}</div>`}
function audit(){return panel(title('audit'),table([T('Time','الوقت'),T('Action','العملية'),T('Reference','المرجع'),T('Role','الدور')],s.events.map(e=>[new Date(e.date).toLocaleString(lang==='ar'?'ar-LB':'en-GB'),L(e.type),esc(e.ref),T(...roles[e.role])])),T('Browser-local event history. Production requires server-side immutable logging.','سجل محلي للمتصفح. الإنتاج يحتاج سجلاً ثابتاً على الخادم.'))}
function settings(){return `<div class="report-grid">${panel(T('Commercial & currency policies','السياسات التجارية والعملات'),`<form id="settings-form" class="panel-body"><div class="form-row">${field(T('Commercial approval above (USD)','الموافقة التجارية فوق (دولار)'),`<input name="commercialLimit" type="number" min="1" value="${s.settings.commercialLimit}" required>`)}${field(T('Discount approval above (%)','موافقة الخصم فوق (%)'),`<input name="discountLimit" type="number" min="0" max="30" value="${s.settings.discountLimit}" required>`)}</div><div class="form-row">${field(T('1 EUR = USD','١ يورو = دولار'),`<input name="eur" type="number" step=".0001" min=".0001" value="${s.settings.rates.EUR}" required>`)}${field(T('1 USD = LBP','١ دولار = ليرة'),`<input name="lbp" type="number" min="1" value="${Math.round(1/s.settings.rates.LBP)}" required>`)}</div><p class="notice">${T('Illustrative rates, not live market quotes. Existing documents keep their original rate. Taxes are configurable examples, not a compliance implementation.','أسعار توضيحية وليست أسعار سوق حية. المستندات السابقة تحافظ على سعرها. الضرائب أمثلة قابلة للضبط وليست تطبيق امتثال ضريبي.')}</p>${field(T('Customer shipping policy','سياسة تسليم العميل'),`<select name="client">${clientOptions()}</select>`)}<label class="checkline"><input name="partial" type="checkbox" checked>${T('Allow partial shipments for this customer','السماح بالتسليم الجزئي لهذا العميل')}</label><button class="btn primary" type="submit">${T('Save policies','حفظ السياسات')}</button></form>`)}${panel(T('Workspace data','بيانات المساحة'),`<div class="panel-body"><div class="data-actions">${btn(T('Download backup JSON','تحميل نسخة JSON'),'backup','',true,'download')}${btn(T('Restore backup','استعادة نسخة'),'restore','',false,'refresh')}${btn(T('Reset demo workspace','إعادة ضبط العرض'),'reset','',false,'refresh')}</div><div class="scope-note"><h3>${T('Concept capabilities & deployment scope','قدرات النموذج ونطاق النشر')}</h3><p>${T('This is a functional portfolio prototype with connected demo transactions. Data is stored locally in this browser.','نموذج عملي للـportfolio بمعاملات تجريبية مترابطة. البيانات محفوظة محلياً في هذا المتصفح.')}</p><p>${T('Roles demonstrate permissions, but are not authentication. No shared database, live banking, payment gateway, e-invoicing or live AI is connected.','الأدوار تعرض الصلاحيات ولا تشكّل تسجيل دخول آمناً. لا توجد قاعدة بيانات مشتركة أو ربط بنك أو دفع أو فوترة إلكترونية أو ذكاء اصطناعي حي.')}</p><p>${T('Production roadmap: multi-tenant backend, server authorization, transaction locking, audit retention, backups, integrations and tax localization.','خارطة الإنتاج: خادم متعدد الشركات، صلاحيات على الخادم، قفل المعاملات، حفظ السجل، نسخ احتياطية، تكاملات وتوطين ضريبي.')}</p></div><div class="health"><span class="chip green">${T('Ledger balanced','الدفتر متوازن')}</span><span class="chip blue">${T('Schema','الإصدار')}: v2</span><span class="chip">${T('Revision','المراجعة')}: ${s.revision}</span></div></div>`)}</div>`}
const views={dashboard,crm,quotes:quotations,sales,customers,inventory,warehouse,purchasing,replenishment:replenish,finance,expenses,reconciliation,reports,approvals,intelligence,portal,audit,settings};
const field=(label,input)=>`<label class="field"><span>${label}</span>${input}</label>`,clientOptions=(id='')=>s.clients.map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${cn(c.id)}</option>`).join(''),productOptions=(id='')=>s.products.map(p=>`<option value="${p.id}" ${id===p.id?'selected':''}>${pn(p.id)}</option>`).join(''),supplierOptions=(id='')=>s.suppliers.map(p=>`<option value="${p.id}" ${id===p.id?'selected':''}>${sn(p.id)}</option>`).join('');
function open(title,body,wide=false){$('#overlay-root').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-head"><div><div class="eyebrow">AS NEXUS</div><h2>${title}</h2></div><button class="icon-btn" data-act="close" aria-label="${T('Close','إغلاق')}">${icon('close')}</button></div><div class="drawer-content">${body}</div></section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('.modal input,.modal select,.modal button')?.focus(),0)}
function close(){$('#overlay-root').innerHTML='';document.body.classList.remove('modal-open')}
function documentFacts(o){const t=E.totals(o);return `<div class="doc-facts"><div><small>${T('Customer','العميل')}</small><strong>${cn(o.client)}</strong></div><div><small>${T('Document currency','عملة المستند')}</small><strong>${o.currency} · ${T('Locked rate','سعر ثابت')}: ${o.rate.toFixed(6)}</strong></div><div><small>${T('Net + tax','الصافي والضريبة')}</small><strong>${M(t.net,o.currency,o.rate)} + ${M(t.tax,o.currency,o.rate)}</strong></div><div><small>${T('Total','الإجمالي')}</small><strong>${M(t.gross,o.currency,o.rate)}</strong></div></div>`}
function detail(kind,id){
 if(kind==='order'){const o=s.orders.find(z=>z.id===id);if(!o)return;open(o.id,`${documentFacts(o)}<div class="facts">${badge(o.status)}<span class="chip">${T('Tax','الضريبة')}: ${N(o.tax)}%</span>${o.creditOverride?`<span class="chip orange">${T('Credit override recorded','استثناء ائتماني مسجّل')}</span>`:''}</div>${table([T('Product','المنتج'),T('Ordered','المطلوب'),T('Reserved','المحجوز'),T('Shipped','المشحون'),T('Unit price','سعر الوحدة'),T('Discount','الخصم')],o.lines.map(l=>[pn(l.product),N(l.qty),N(l.allocations.reduce((a,x)=>a+x.qty,0)),N(l.shipped),M(l.unit,o.currency,o.rate),N(l.discount)+'%']))}<div class="allocation-list">${o.lines.flatMap(l=>l.allocations.map(a=>{const lot=s.lots.find(z=>z.id===a.lot);return `<div><span>${pn(l.product)} · ${wh(lot.warehouse)}</span><small>${esc(lot.id)} · ${lot.expiry} · ${N(a.qty)}</small></div>`})).join('')}</div><div class="modal-actions">${o.status==='approval'?btn(T('Review & approve','مراجعة واعتماد'),'form',`data-mode="approve" data-id="${id}"`,true):''}${['ready','partial'].includes(o.status)?btn(T('Pick, pack & ship','تجهيز وشحن'),'form',`data-mode="ship" data-id="${id}"`,true,'truck'):''}${['ready','partial','backorder'].includes(o.status)?btn(T('Refresh allocation','تحديث الحجز'),'direct',`data-type="reserve" data-id="${id}"`):''}${!o.lines.some(l=>l.shipped)&&o.status!=='cancelled'?btn(T('Cancel order','إلغاء الطلب'),'direct',`data-type="cancel" data-id="${id}"`):''}</div>`,true)}
 if(kind==='quote'){const q=s.quotes.find(z=>z.id===id);open(q.id,`${documentFacts(q)}${table([T('Product','المنتج'),T('Quantity','الكمية'),T('Price','السعر'),T('Discount','الخصم')],q.lines.map(l=>[pn(l.product),N(l.qty),M(l.unit,q.currency,q.rate),N(l.discount)+'%']))}<div class="modal-actions">${q.status==='draft'?btn(T('Convert to order','تحويل لطلب'),'direct',`data-type="convert" data-id="${id}"`,true):badge(q.status)}</div>`,true)}
 if(kind==='invoice'){const i=s.invoices.find(z=>z.id===id);open(i.id,`<div class="doc-facts"><div><small>${T('Customer','العميل')}</small><strong>${cn(i.client)}</strong></div><div><small>${T('Due date','الاستحقاق')}</small><strong>${i.dueDate}</strong></div><div><small>${T('Invoice amount','قيمة الفاتورة')}</small><strong>${M(i.amount,i.currency,i.rate)}</strong></div><div><small>${T('Remaining due','الرصيد المستحق')}</small><strong>${M(E.due(i),i.currency,i.rate)}</strong></div></div>${table([T('Product','المنتج'),T('Invoiced','المفوتر'),T('Returned','المرتجع'),T('Net amount','الصافي')],i.lines.map(l=>[pn(l.product),N(l.qty),N(l.returned),M(l.net,i.currency,i.rate)]))}<div class="modal-actions">${E.due(i)>0?btn(T('Record payment','تسجيل دفعة'),'form',`data-mode="pay" data-id="${id}"`,true,'wallet'):''}${i.lines.some(l=>l.returned<l.qty)?btn(T('Return / credit','مرتجع / إشعار دائن'),'form',`data-mode="return" data-id="${id}"`,false,'return'):''}${btn(T('Download printable invoice','تحميل فاتورة للطباعة'),'printinvoice',`data-id="${id}"`,false,'download')}</div><p class="notice">${T('Payments and credit notes remain linked to this invoice. A return reduces revenue and restores the original inventory cost.','الدفعات والإشعارات متصلة بهذه الفاتورة. المرتجع يعكس الإيراد ويعيد كلفة المخزون الأصلية.')}</p>`,true)}
 if(kind==='purchase'){const p=s.purchases.find(z=>z.id===id),value=p.lines.reduce((a,l)=>a+l.received*l.unit,0);open(p.id,`<h3>${sn(p.supplier)}</h3><div class="facts">${badge(p.status)}<span class="chip">${T('Received payable','المستحق المستلم')}: ${M(value-p.paid)}</span></div>${table([T('Product','المنتج'),T('Ordered','المطلوب'),T('Received','المستلم'),T('Unit cost','كلفة الوحدة')],p.lines.map(l=>[pn(l.product),N(l.qty),N(l.received),M(l.unit)]))}<div class="modal-actions">${p.status==='approval'?btn(T('Approve request','اعتماد الطلب'),'direct',`data-type="purchaseApprove" data-id="${id}"`,true):''}${['ordered','partial'].includes(p.status)?btn(T('Receive items','استلام المنتجات'),'form',`data-mode="receive" data-id="${id}"`,true):''}${value>p.paid?btn(T('Pay supplier','دفع للمورّد'),'form',`data-mode="supplierpay" data-id="${id}"`):''}</div>`,true)}
 if(kind==='product'){const p=s.products.find(z=>z.id===id);open(pn(id),`${table([T('Lot','الدفعة'),T('Location','الموقع'),T('On hand','الموجود'),T('Reserved','المحجوز'),T('Expiry','الصلاحية'),T('Status','الحالة'),T('Cost','الكلفة')],s.lots.filter(l=>l.product===id&&l.qty).sort((a,b)=>a.expiry.localeCompare(b.expiry)).map(l=>[l.id,wh(l.warehouse),N(l.qty),N(l.reserved),l.expiry,`<span class="chip ${l.status==='quarantine'||l.expiry<E.today?'red':l.expiry<'2026-11-07'?'orange':'green'}">${l.status==='quarantine'?T('Quarantine','حجر'):l.expiry<E.today?T('Expired','منتهية'):T('Saleable','صالح للبيع')}</span>`,M(l.unitCost)]))}<div class="modal-actions">${btn(T('Transfer stock','نقل مخزون'),'form',`data-mode="transfer" data-product="${p.id}"`,true)}${btn(T('Submit count','تسجيل جرد'),'form',`data-mode="count" data-product="${p.id}"`)}</div>`,true)}
 if(kind==='client'){const c=s.clients.find(z=>z.id===id);open(cn(id),`<div class="doc-facts"><div><small>${T('Outstanding','الرصيد')}</small><strong>${M(E.outstanding(s,id))}</strong></div><div><small>${T('Credit limit','حد الائتمان')}</small><strong>${M(c.limit)}</strong></div><div><small>${T('Opening balance','الرصيد الافتتاحي')}</small><strong>${M(c.opening)}</strong></div><div><small>${T('Shipping advice','سياسة التسليم')}</small><strong>${c.partial?T('Partial allowed','الجزئي مسموح'):T('Complete only','كامل فقط')}</strong></div></div>${invoiceTable(s.invoices.filter(i=>i.client===id))}<div class="modal-actions">${btn(T('New quotation','عرض جديد'),'form',`data-mode="quote" data-client="${id}"`,true)}</div>`,true)}
}
function rowHTML(p='P01',qty=1,unit,discount=0){const prod=s.products.find(z=>z.id===p);return `<div class="line-row"><select name="product" aria-label="${T('Product','المنتج')}">${productOptions(p)}</select><input name="qty" type="number" min="1" value="${qty}" required aria-label="${T('Quantity','الكمية')}"><input name="unit" type="number" min=".01" step=".01" value="${unit??prod.price}" required aria-label="${T('Unit price','سعر الوحدة')}"><input name="discount" type="number" min="0" max="30" value="${discount}" aria-label="${T('Discount','الخصم')}"><button class="icon-btn" type="button" data-act="removeline" aria-label="${T('Remove line','حذف بند')}">${icon('close')}</button></div>`}
function form(mode,extra={}){formMode=mode;formExtra=extra;let body='',label=L(mode);const o=s.orders.find(z=>z.id===extra.id),i=s.invoices.find(z=>z.id===extra.id),po=s.purchases.find(z=>z.id===extra.id),lead=s.leads.find(z=>z.id===extra.lead);
 if(['create','quote','purchase'].includes(mode)){label=mode==='create'?T('New sales order','طلب بيع جديد'):mode==='quote'?T('New quotation','عرض سعر جديد'):T('Purchase request','طلب شراء');body=`<div class="form-row">${field(mode==='purchase'?T('Supplier','المورّد'):T('Customer','العميل'),`<select name="${mode==='purchase'?'supplier':'client'}">${mode==='purchase'?supplierOptions(extra.supplier):clientOptions(extra.client||lead?.client)}</select>`)}${mode!=='purchase'?field(T('Document currency','عملة المستند'),'<select name="currency"><option>USD</option><option>EUR</option><option>LBP</option></select>'):''}</div>${mode!=='purchase'?field(T('Illustrative sales tax','ضريبة بيع نموذجية'),`<select name="tax"><option value="0">0%</option><option value="11">11%</option><option value="20">20%</option></select>`):''}<div class="line-labels"><span>${T('Product','المنتج')}</span><span>${T('Qty','كمية')}</span><span>${T('USD / unit','دولار / وحدة')}</span><span>${T('Disc %','خصم %')}</span></div><div id="form-lines">${rowHTML(extra.product||'P01',+extra.qty||1,mode==='purchase'?s.products.find(p=>p.id===(extra.product||'P01')).cost:undefined)}</div><div class="line-actions">${btn(T('Add product','إضافة منتج'),'addline','',false,'plus')}${mode!=='purchase'?`<select id="kit-select"><option value="">${T('Add a kit…','إضافة مجموعة…')}</option>${s.kits.map(k=>`<option value="${k.id}">${T(k.name,k.arabic)}</option>`).join('')}</select>`:''}</div><p class="notice">${T('Prices are entered in USD base. Document currency uses its saved exchange rate.','الأسعار تدخل بالدولار الأساسي. عملة المستند تستخدم سعر الصرف المحفوظ.')}</p>`;}
 if(mode==='approve'){label=T('Review order approval','مراجعة الموافقة على الطلب');const c=s.clients.find(c=>c.id===o.client),exposure=E.outstanding(s,c.id)+s.orders.filter(z=>z.id!==o.id&&z.client===c.id&&!['approval','cancelled','delivered'].includes(z.status)).reduce((a,z)=>a+z.lines.reduce((n,l)=>n+(l.qty-l.shipped)*l.unit*(1-l.discount/100)*(1+z.tax/100),0),0)+E.totals(o).gross;body=`${documentFacts(o)}<div class="notice">${T('Total exposure including approved open orders','التعرّض الكامل مع الطلبات المفتوحة المعتمدة')}: <strong>${M(exposure)}</strong><br>${T('Customer credit limit','حد ائتمان العميل')}: ${M(c.limit)}<br>${T('Commercial policy threshold','حد السياسة التجارية')}: ${M(s.settings.commercialLimit)}</div><label class="checkline"><input type="checkbox" name="override">${T('Explicitly authorize a credit limit override (administrator only).','الموافقة الصريحة على تجاوز حد الائتمان (مدير فقط).')}</label>`;}
 if(mode==='ship'){label=T('Pick, pack & ship','تجهيز وشحن');body=`<p class="notice">${T('Confirm physically picked quantities. Each shipment creates its own invoice. Unshipped quantities stay reserved or backordered.','أكد الكميات المجهّزة فعلياً. كل شحنة تنشئ فاتورتها. المتبقي يبقى محجوزاً أو ينتظر المخزون.')}</p>${o.lines.map((l,n)=>field(`${pn(l.product)} · ${T('Remaining','المتبقي')}: ${N(l.qty-l.shipped)} · ${T('Reserved','محجوز')}: ${N(l.allocations.reduce((a,x)=>a+x.qty,0))}`,`<input name="q${n}" type="number" min="0" max="${l.allocations.reduce((a,x)=>a+x.qty,0)}" value="${l.allocations.reduce((a,x)=>a+x.qty,0)}" required>`)).join('')}<label class="checkline"><input type="checkbox" name="packed" required>${T('Picking checked, items packed and ready to dispatch.','تم تدقيق التجهيز وتوضيب المنتجات وهي جاهزة للشحن.')}</label>`;}
 if(mode==='pay'){label=T('Record customer payment','تسجيل دفعة عميل');body=`<div class="notice">${T('Remaining due','المستحق')}: ${M(E.due(i),i.currency,i.rate)}</div>${field(T('Amount in invoice currency','المبلغ بعملة الفاتورة'),`<input name="amount" type="number" min=".01" step=".01" max="${Math.ceil(E.due(i)/i.rate*100)/100}" value="${E.round(E.due(i)/i.rate)}" required>`)}<input type="hidden" name="documentCurrency" value="1">`;}
 if(mode==='return'){label=T('Return & credit note','مرتجع وإشعار دائن');body=`${field(T('Invoice line','بند الفاتورة'),`<select name="line">${i.lines.map((l,n)=>`<option value="${n}">${pn(l.product)} · ${T('Returnable','قابل للإرجاع')}: ${N(l.qty-l.returned)}</option>`).join('')}</select>`)}${field(T('Return quantity','كمية المرتجع'),'<input name="qty" type="number" min="1" value="1" required>')}<label class="checkline"><input type="checkbox" name="quarantine">${T('Quarantine damaged goods instead of making them available.','حجر المنتجات المتضرّرة بدلاً من إتاحتها للبيع.')}</label><p class="notice">${T('Paid amounts above the corrected invoice total are recorded as a cash refund.','المبالغ المدفوعة الزائدة عن الإجمالي المعدّل تسجّل كاسترداد نقدي.')}</p>`;}
 if(mode==='receive'){label=T('Receive purchase items','استلام منتجات الشراء');body=`${po.lines.map((l,n)=>field(`${pn(l.product)} · ${T('Remaining','المتبقي')}: ${N(l.qty-l.received)}`,`<input name="q${n}" type="number" min="0" max="${l.qty-l.received}" value="${l.qty-l.received}" required>`)).join('')}${field(T('Receiving warehouse','مستودع الاستلام'),`<select name="warehouse"><option value="main">${wh('main')}</option><option value="branch">${wh('branch')}</option></select>`)}${field(T('Lot expiry','صلاحية الدفعة'),'<input name="expiry" type="date" value="2027-10-08" required>')}<p class="notice">${T('Only received quantities enter inventory and supplier payables.','الكميات المستلمة فقط تدخل المخزون وذمم المورّد.')}</p>`;}
 if(mode==='supplierpay'){label=T('Pay supplier','دفع للمورّد');const unpaid=E.round(po.lines.reduce((a,l)=>a+l.received*l.unit,0)-po.paid);body=`${field(T('Amount (USD)','المبلغ (دولار)'),`<input name="amount" type="number" step=".01" min=".01" max="${unpaid}" value="${unpaid}" required>`)}`;}
 if(mode==='transfer'||mode==='count'){label=mode==='transfer'?T('Transfer stock','نقل مخزون'):T('Submit physical count','إرسال جرد فعلي');body=`${field(T('Product','المنتج'),`<select name="product">${productOptions(extra.product)}</select>`)}${field(mode==='transfer'?T('Source warehouse','مستودع المصدر'):T('Warehouse','المستودع'),`<select name="${mode==='transfer'?'from':'warehouse'}"><option value="main">${wh('main')}</option><option value="branch">${wh('branch')}</option></select>`)}${field(mode==='transfer'?T('Transfer quantity','كمية النقل'):T('Physical quantity counted','الكمية المعدودة فعلياً'),`<input name="${mode==='transfer'?'qty':'counted'}" type="number" min="${mode==='transfer'?1:0}" value="${mode==='transfer'?1:extra.product?s.products.find(p=>p.id===extra.product).stock.main:80}" required>`)}<p class="notice">${mode==='transfer'?T('Moves available units to the other location and preserves lot cost and expiry.','ينقل القطع المتاحة للموقع الآخر مع حفظ الكلفة والصلاحية.'):T('A variance is submitted for administrator approval. No stock movement before approval.','الفرق يُرسل لموافقة المدير. المخزون لا يتغير قبل الموافقة.')}</p>`;}
 if(mode==='expense'){label=T('Submit expense','تسجيل مصروف');body=`${field(T('Category','الفئة'),`<select name="category">${['Rent','Logistics','Software','Marketing','Payroll'].map(c=>`<option value="${c}">${L(c)}</option>`).join('')}</select>`)}${field(T('Amount (USD)','المبلغ (دولار)'),'<input name="amount" type="number" min=".01" step=".01" required>')}`;}
 if(mode==='lead'){label=T('New opportunity','فرصة جديدة');body=`${field(T('Opportunity name','اسم الفرصة'),'<input name="name" required>')}${field(T('Arabic name','الاسم العربي'),'<input name="arabic">')}${field(T('Customer','العميل'),`<select name="client">${clientOptions()}</select>`)}${field(T('Estimated value (USD)','القيمة المقدّرة (دولار)'),'<input name="value" type="number" min="1" required>')}`;}
 if(mode==='client'){label=T('Add customer','إضافة عميل');body=`${field(T('Company name','اسم الشركة'),'<input name="name" required>')}${field(T('Arabic name','الاسم العربي'),'<input name="arabic">')}${field(T('City','المدينة'),'<input name="city" value="Beirut">')}${field(T('Credit limit (USD)','حد الائتمان (دولار)'),'<input name="limit" type="number" min="0" value="3000" required>')}${field(T('Tier','الفئة'),`<select name="tier">${['Platinum','Gold','Silver'].map(c=>`<option value="${c}">${tier(c)}</option>`).join('')}</select>`)}`;}
 if(mode==='match'){label=T('Match bank payment','مطابقة دفعة البنك');const b=s.statements.find(z=>z.id===extra.id),p=s.payments.filter(p=>!p.matched&&E.round(p.amount)===E.round(b.amount));body=`<div class="notice">${esc(b.reference)} · ${M(b.amount)}</div>${field(T('Eligible existing payment','دفعة مسجّلة مطابقة'),`<select name="payment" required><option value="">${T('Select payment','اختر دفعة')}</option>${p.map(z=>`<option value="${z.id}">${z.id} · ${z.ref} · ${z.date}</option>`).join('')}</select>`)}${!p.length?`<p class="notice">${T('No eligible payments. This statement entry stays unresolved.','لا توجد دفعة مطابقة. تبقى حركة الكشف معلّقة.')}</p>`:''}`;}
 if(mode==='bankimport'){label=T('Import statement CSV','استيراد كشف CSV');body=`<p class="notice">${T('CSV columns: date,amount,reference. Positive = deposit; negative = withdrawal. USD base only.','أعمدة CSV: date,amount,reference. موجب للإيداع وسالب للسحب. الدولار الأساسي فقط.')}</p><input name="csv" type="file" accept=".csv,text/csv" required><a class="template-link" href="data:text/csv;charset=utf-8,date%2Camount%2Creference%0A2026-10-08%2C175%2CDeposit" download="statement-template.csv">${T('Download template','تحميل النموذج')}</a>`;}
 open(label,`<form id="action-form">${body}<div class="modal-actions"><button class="btn primary" type="submit">${T('Confirm & save','تأكيد وحفظ')}</button><button type="button" class="btn" data-act="close">${T('Cancel','إلغاء')}</button></div></form>`,['create','quote','purchase','ship','approve'].includes(mode));}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function csvExport(){let records,headers;if(['sales','warehouse','approvals'].includes(page)){headers=['order','customer','product','qty','shipped','reserved','unit_USD','discount_pct','status'];records=s.orders.flatMap(o=>o.lines.map(l=>[o.id,cn(o.client),pn(l.product),l.qty,l.shipped,l.allocations.reduce((a,x)=>a+x.qty,0),l.unit,l.discount,o.status]))}else if(['inventory','replenishment'].includes(page)){headers=['product','lot','warehouse','qty','reserved','expiry','cost_USD','status'];records=s.lots.map(l=>[pn(l.product),l.id,l.warehouse,l.qty,l.reserved,l.expiry,l.unitCost,l.status])}else if(page==='crm'){headers=['lead','name','customer','value_USD','stage'];records=s.leads.map(l=>[l.id,T(l.name,l.arabic),cn(l.client),l.value,l.stage])}else if(page==='quotes'){headers=['quote','customer','net_USD','tax_USD','gross_USD','currency','rate','status'];records=s.quotes.map(q=>[q.id,cn(q.client),E.totals(q).net,E.totals(q).tax,E.totals(q).gross,q.currency,q.rate,q.status])}else if(page==='customers'){headers=['customer','name','credit_USD','outstanding_USD','partial_shipping'];records=s.clients.map(c=>[c.id,cn(c.id),c.limit,E.outstanding(s,c.id),c.partial])}else if(page==='purchasing'){headers=['purchase','supplier','product','ordered','received','unit_cost_USD','status'];records=s.purchases.flatMap(p=>p.lines.map(l=>[p.id,sn(p.supplier),pn(l.product),l.qty,l.received,l.unit,p.status]))}else if(page==='reconciliation'){headers=['statement','date','amount_USD','reference','match'];records=s.statements.map(b=>[b.id,b.date,b.amount,b.reference,b.match||''])}else if(page==='expenses'){headers=['expense','category','amount_USD','status'];records=s.expenses.map(e=>[e.id,e.category,e.amount,e.status])}else if(page==='audit'){headers=['revision','action','reference','role','time'];records=s.events.map(e=>[e.id,e.type,e.ref,e.role,e.date])}else if(page==='finance'||page==='portal'){headers=['invoice','customer','gross_USD','credit_USD','paid_USD','due_USD','currency','exchange_rate'];records=s.invoices.map(i=>[i.id,cn(i.client),i.amount,i.credit,i.paid,E.due(i),i.currency,i.rate])}else{headers=['journal','date','reference','account','debit_USD','credit_USD'];records=s.journal.flatMap(j=>j.lines.map(l=>[j.id,j.date,j.ref,l.account,l.debit,l.credit]))}const cell=x=>{let str=String(x??'');if(/^[=+@-]/.test(str)&&!Number.isFinite(+str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"'};download('AS-NEXUS-'+page+'.csv','\uFEFF'+[headers,...records].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function printInvoice(id){const i=s.invoices.find(z=>z.id===id);download(i.id+'.html',`<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><meta charset="utf-8"><title>${i.id}</title><style>body{font:15px Arial,sans-serif;padding:48px;color:#142239}h1{font-size:32px}table{border-collapse:collapse;width:100%;margin:30px 0}td,th{border-bottom:1px solid #ddd;padding:14px;text-align:start}header{display:flex;justify-content:space-between}p{line-height:1.7}button{padding:12px;border:0;background:#3159eb;color:white}@media print{button{display:none}body{padding:12px}}</style><header><div><h1>NEXA</h1><p>${T('Demo distribution company','شركة توزيع تجريبية')}<br>AS NEXUS · AS DESIGN LB</p></div><div><h1>${i.id}</h1><p>${i.date}<br>${T('Due','الاستحقاق')}: ${i.dueDate}</p></div></header><h2>${esc(cn(i.client))}</h2>${table([T('Product','المنتج'),T('Qty','الكمية'),T('Net','الصافي')],i.lines.map(l=>[esc(pn(l.product)),l.qty,M(l.net,i.currency,i.rate)]))}<p>${T('Net','الصافي')}: ${M(i.net,i.currency,i.rate)}<br>${T('Tax','الضريبة')}: ${M(i.amount-i.net,i.currency,i.rate)}<br><strong>${T('Total','الإجمالي')}: ${M(i.amount,i.currency,i.rate)}</strong><br>${T('Credits','الإشعارات')}: ${M(i.credit,i.currency,i.rate)}<br>${T('Paid','المدفوع')}: ${M(i.paid,i.currency,i.rate)}<br><strong>${T('Due','المستحق')}: ${M(E.due(i),i.currency,i.rate)}</strong></p><p>${T('Demonstration invoice. Not a tax-compliant legal invoice.','فاتورة عرض تجريبية وليست فاتورة ضريبية قانونية.')}</p><button onclick="window.print()">${T('Print / Save PDF','طباعة / حفظ PDF')}</button></html>`,'text/html;charset=utf-8')}
function search(){open(T('Search your workspace','ابحث في المساحة'),`<input id="global-search" class="global-input" placeholder="${T('Product, customer, order or screen…','منتج، عميل، طلب أو شاشة…')}" autofocus><div id="search-results">${searchResults('')}</div>`,true);setTimeout(()=>$('#global-search').focus(),30)}
function searchResults(q){q=q.toLowerCase();const rows=[...Object.keys(pages).map(p=>({name:title(p),sub:T('Screen','شاشة'),page:p})),...s.products.map(p=>({name:pn(p.id),sub:p.sku,id:p.id,kind:'product'})),...s.clients.map(c=>({name:cn(c.id),sub:c.id,id:c.id,kind:'client'})),...s.orders.map(o=>({name:o.id,sub:cn(o.client),id:o.id,kind:'order'})),...s.invoices.map(i=>({name:i.id,sub:cn(i.client),id:i.id,kind:'invoice'}))].filter(r=>(r.name+' '+r.sub).toLowerCase().includes(q)).slice(0,18);return rows.map(r=>`<button class="search-result" ${r.page?`data-page="${r.page}"`:`data-act="detail" data-kind="${r.kind}" data-id="${r.id}"`}>${icon(r.page?pages[r.page][2]:'search')}<div><strong>${esc(r.name)}</strong><div class="cell-sub">${esc(r.sub)}</div></div></button>`).join('')||empty()}
function ask(query){const q=(query||$('#ask-input').value).toLowerCase(),m=E.metrics(s);let answer,target;if(/stock|inventory|reorder|مخزون|توريد/.test(q)){const r=s.products.map(p=>({p,r:E.replenishment(s,p)})).filter(z=>z.r.suggested);answer=T(`There are ${r.length} replenishment exceptions. `,'يوجد '+N(r.length)+' استثناءات توريد. ')+r.map(z=>`${pn(z.p.id)}: ${N(z.r.suggested)} ${T('units proposed','قطعة مقترحة')} (${T('forecast','المتوقع')} ${N(z.r.forecast)})`).join(' · ');target='replenishment'}else if(/credit|receivable|ائتمان|ديون/.test(q)){answer=T('Credit exposure is checked using opening balances, unpaid invoices and approved unshipped orders. Current receivables: ','التعرّض يُراجع باستخدام الافتتاحي والفواتير المستحقة والطلبات المعتمدة غير المشحونة. الذمم الحالية: ')+M(m.receivables);target='customers'}else if(/profit|margin|ربح|هامش/.test(q)){answer=T('Net sales ','صافي البيع ')+M(m.revenue)+T(' minus cost of sales ',' ناقص كلفة البيع ')+M(m.cogs)+T(' and operating expenses / variance ',' والمصاريف التشغيلية / فرق الجرد ')+M(m.expenses)+T(' gives net operating profit ',' يعطي ربحاً تشغيلياً ')+M(m.netProfit);target='reports'}else if(/cash|bank|نقد|بنك/.test(q)){answer=T('Cash ledger balance is ','رصيد دفتر النقد ')+M(m.cash)+T('. Matching a bank entry does not change this amount.','. مطابقة حركة البنك لا تغيّر هذا المبلغ.');target='reconciliation'}else{answer=T('I can explain stock, credit, profit or cash using current records. Choose one of those topics.','أقدر فسّر المخزون والائتمان والربح والنقد من السجلات الحالية. اختر واحداً منها.');target='reports'}$('#answer').innerHTML=`<span class="chip blue">${T('Rule-based analysis · current workspace','تحليل بالقواعد · المساحة الحالية')}</span><p>${answer}</p>${btn(T('Open evidence','افتح الدليل'),'goto',`data-page="${target}"`)}`}
function simulate(){if(!$('#sim-volume'))return;const v=+$('#sim-volume').value,d=+$('#sim-discount').value,c=+$('#sim-cost').value,m=E.metrics(s),rev=m.revenue*(1+v/100)*(1-d/100),cost=m.cogs*(1+v/100)*(1+c/100),net=rev-cost-m.expenses;$('#sim-volume-value').textContent=(v>0?'+':'')+v+'%';$('#sim-discount-value').textContent=d+'%';$('#sim-cost-value').textContent=c+'%';$('#sim-result').innerHTML=`<span class="muted">${T('Projected net operating profit','صافي الربح التشغيلي المتوقع')}</span><div class="sim-big">${M(net)}</div><span class="chip ${net>=m.netProfit?'green':'orange'}">${T('Change vs baseline','التغيّر عن الأساس')}: ${M(net-m.netProfit)}</span><div class="facts"><span>${T('Sales','البيع')}: ${M(rev)}</span><span>${T('Cost','الكلفة')}: ${M(cost)}</span></div>`}
const tour=[['dashboard','Connected business overview','نظرة مترابطة على الشركة'],['crm','Opportunity to quotation','من الفرصة إلى عرض السعر'],['sales','Multi-item orders and credit controls','طلبات متعددة المنتجات ورقابة الائتمان'],['warehouse','FEFO allocation and partial shipments','حجز حسب الصلاحية وتسليم جزئي'],['inventory','Traceable lots and virtual kits','دفعات قابلة للتتبع ومجموعات افتراضية'],['purchasing','Approve, receive partially and pay','اعتماد واستلام جزئي ودفع'],['replenishment','Demand-driven replenishment','توريد بحسب الطلب'],['finance','Invoices, returns and payments','فواتير ومرتجعات ودفعات'],['reconciliation','Match without double-posting','مطابقة دون تكرار القيد'],['reports','Financial and inventory analytics','تحليلات المالية والمخزون'],['intelligence','Evidence-based decisions and scenarios','قرارات وسيناريوهات مبنية على الأدلة'],['portal','Customer shopping connected to operations','تجربة العميل متصلة بالعمليات']];
function showTour(){const [p,en,ar]=tour[tourStep];page=p;close();render();window.scrollTo({top:0});simulate();$('.tour-caption')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="tour-caption"><span class="num">${tourStep+1}</span><div><strong>${T(en,ar)}</strong><p>${T('Explore the screen, then continue. No demo transactions are changed.','جرّب الشاشة ثم تابع. الجولة لا تغيّر المعاملات.')}</p></div>${btn(T('Next','التالي'),'tournext','',true)}${btn(T('End tour','إنهاء الجولة'),'tourend')}</div>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act],[data-page]');if(!b)return;if(b.type!=='submit')e.preventDefault();if(b.dataset.page){page=b.dataset.page;close();render();window.scrollTo({top:0});simulate();return}const a=b.dataset.act,d=b.dataset;if(a==='language'){lang=lang==='en'?'ar':'en';localStorage.setItem('nexus-lang',lang);close();render();simulate()}if(a==='theme'){dark=!dark;localStorage.setItem('nexus-theme',dark?'dark':'light');render();simulate()}if(a==='menu')$('.sidebar').classList.toggle('open');if(a==='close')close();if(a==='search')search();if(a==='detail')detail(d.kind,d.id);if(a==='form')form(d.mode,{...d});if(a==='direct'){if(d.type==='cancel'){open(T('Cancel this order?','إلغاء هذا الطلب؟'),`<p>${T('Reserved stock will be released. This document stays in the audit history.','سيتم تحرير الحجز ويظل المستند في السجل.')}</p><div class="modal-actions">${btn(T('Confirm cancellation','تأكيد الإلغاء'),'cancelconfirm',`data-id="${d.id}"`,true)}</div>`)}else commit(d.type,{id:d.id})}if(a==='cancelconfirm')commit('cancel',{id:d.id});if(a==='export')csvExport();if(a==='printinvoice')printInvoice(d.id);if(a==='addline')$('#form-lines').insertAdjacentHTML('beforeend',rowHTML('P02',1,formMode==='purchase'?s.products[1].cost:undefined));if(a==='removeline')b.closest('.line-row').remove();if(a==='cartadd'){const p=s.products.find(z=>z.id===d.product),l=cart.find(z=>z.product===p.id&&!z.kit);if(l)l.qty++;else cart.push({product:p.id,qty:1,unit:p.price,discount:0});render()}if(a==='kitadd'){const k=s.kits.find(k=>k.id===d.id);k.items.forEach(i=>{const l=cart.find(z=>z.product===i.product&&z.kit===k.id);if(l)l.qty+=i.qty;else cart.push({...i,discount:0,kit:k.id})});render();toast(T('Kit components added to your order.','تمت إضافة مكوّنات المجموعة للطلب.'))}if(a==='cartremove'){cart.splice(+d.index,1);render()}if(a==='cartsubmit'){const previous=role;if(role==='admin')role='customer';const ok=commit('create',{client:portalClient,lines:cart,currency,tax:0,source:'Customer portal'});role=previous;if(ok){cart=[];render()}}if(a==='backup')download('AS-NEXUS-Backup.json',JSON.stringify(s,null,2),'application/json');if(a==='restore'){open(T('Restore workspace backup','استعادة النسخة الاحتياطية'),`<p class="notice">${T('Restoring replaces the current browser workspace. A backup of current data downloads first.','الاستعادة تستبدل بيانات المتصفح. سيتم تحميل نسخة من البيانات الحالية أولاً.')}</p><input id="restore-file" type="file" accept=".json,application/json">`)}if(a==='reset'){open(T('Reset demo workspace?','إعادة ضبط العرض؟'),`<p>${T('A backup downloads before resetting all demo records.','سيتم تحميل نسخة قبل إعادة ضبط كل السجلات.')}</p><div class="modal-actions">${btn(T('Back up & reset','نسخ وإعادة ضبط'),'resetconfirm','',true)}</div>`)}if(a==='resetconfirm'){download('AS-NEXUS-Before-Reset.json',JSON.stringify(s),'application/json');s=E.seed();localStorage.setItem(KEY,JSON.stringify(s));cart=[];close();render();toast(T('Demo workspace reset.','تمت إعادة ضبط العرض.'))}if(a==='ask')ask(d.query);if(a==='tour'){tourStep=0;showTour()}if(a==='tournext'){tourStep++;if(tourStep>=tour.length){tourStep=-1;$('.tour-caption').remove()}else showTour()}if(a==='tourend'){tourStep=-1;$('.tour-caption').remove()}});
document.addEventListener('change',async e=>{const t=e.target;if(t.name==='client'&&t.closest('#settings-form')){t.closest('form').querySelector('[name=partial]').checked=s.clients.find(c=>c.id===t.value).partial}if(t.id==='role'){role=t.value;toast(T('Demo role changed. Actions follow role permissions.','تغيّر الدور التجريبي. العمليات تخضع لصلاحيات الدور.'))}if(t.id==='currency'){currency=t.value;render();simulate()}if(t.id==='portal-client'){portalClient=t.value;cart=[];render()}if(t.dataset.lead)commit('stage',{id:t.dataset.lead,stage:t.value});if(t.dataset.cart!==undefined){const q=+t.value;if(Number.isInteger(q)&&q>0){cart[+t.dataset.cart].qty=q;render()}else toast(T('Enter a valid quantity.','أدخل كمية صحيحة.'),true)}if(t.name==='product'&&t.closest('.line-row')){t.closest('.line-row').querySelector('[name="unit"]').value=s.products.find(p=>p.id===t.value)[formMode==='purchase'?'cost':'price']}if(t.id==='kit-select'&&t.value){const k=s.kits.find(k=>k.id===t.value);k.items.forEach(i=>$('#form-lines').insertAdjacentHTML('beforeend',rowHTML(i.product,i.qty,i.unit)));t.value=''}if(t.id==='restore-file'){try{const restored=JSON.parse(await t.files[0].text());E.validate(restored);download('AS-NEXUS-Before-Restore.json',JSON.stringify(s),'application/json');restored.revision=s.revision+1;stateSave(restored);close();render();toast(T('Backup restored.','تمت استعادة النسخة.'))}catch{toast(T('Backup rejected. Use a valid AS NEXUS v2 backup.','رُفضت النسخة. استخدم نسخة AS NEXUS v2 سليمة.'),true)}}});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){const q=e.target.value.toLowerCase();$$('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))}if(e.target.id==='global-search')$('#search-results').innerHTML=searchResults(e.target.value);if(e.target.id.startsWith('sim-'))simulate()});
document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='settings-form'){const f=new FormData(e.target);commit('settings',{...Object.fromEntries(f),partial:f.has('partial')});return}if(e.target.id!=='action-form')return;const f=new FormData(e.target),x={...formExtra,...Object.fromEntries(f)};if(['create','quote','purchase'].includes(formMode))x.lines=$$('#form-lines .line-row').map(r=>Object.fromEntries(['product','qty','unit','discount'].map(k=>[k,r.querySelector(`[name="${k}"]`).value])));if(formMode==='approve')x.override=f.has('override');if(formMode==='return')x.quarantine=f.has('quarantine');if(formMode==='ship'||formMode==='receive'){const doc=formMode==='ship'?s.orders.find(z=>z.id===x.id):s.purchases.find(z=>z.id===x.id);x.quantities=doc.lines.map((l,n)=>+f.get('q'+n))}if(formMode==='bankimport'){try{x.rows=parseCSV(await f.get('csv').text())}catch{toast(T('Invalid CSV. Use the provided template.','ملف CSV غير صالح. استخدم النموذج.'),true);return}}commit(formMode,x)});
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x))rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}if(quoted)throw Error('CSV');const h=rows.shift()?.map(x=>x.replace(/^\uFEFF/,'').trim());if(h?.join(',')!=='date,amount,reference')throw Error('CSV');return rows.map(r=>({date:r[0],amount:Number(r[1]),reference:r[2]}))}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();$('.sidebar')?.classList.remove('open')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search()}if(e.key==='Enter'&&e.target.id==='ask-input'){e.preventDefault();ask()}if(e.key==='Tab'&&$('.modal')){const nodes=$$('.modal button,.modal input,.modal select,.modal a').filter(n=>!n.disabled&&n.offsetParent!==null);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('storage',e=>{if(e.key===KEY)toast(T('Another tab updated the workspace. Reload before editing.','حدّثت علامة أخرى المساحة. أعد التحميل قبل التعديل.'),true)});
render();simulate();
